effect.shader:
vec3 sat3v(vec3 c){ return clamp(c, vec3(0.0), vec3(1.0)); }
float lum(vec3 c){ return dot(c, vec3(0.2126, 0.7152, 0.0722)); }

// Positions are anchored on acScreenNorm - the engine's own screen position for
// this fragment - so the anchor never depends on the matrix. Only the DELTA goes
// through acLayerToScreen, and the w=0 multiply cancels the translation, so a
// layer-space offset becomes a screen-space offset exactly. fetchL(acLayerNorm)
// therefore returns texture2DCv(inputImg.texture, acScreenNorm), the engine idiom.
vec2 lpToScreen(vec2 v){ return acScreenNorm + (vec4(v - acLayerNorm, 0.0, 0.0) * acLayerToScreen).xy; }
vec4 fetchL(vec2 lp){ return texture2DCv(inputImg.texture, clamp(lpToScreen(lp), 0.0, 1.0)); }

// Chroma-only distance: divide out the luminance first, so two colours of the
// same hue but different brightness land on top of each other. That is what
// makes the Hue match mode usable on a shaded surface.
float hueDist(vec3 a, vec3 b){
float la = max(lum(a), 1e-4);
float lb = max(lum(b), 1e-4);
return length(a / la - b / lb);
}

// One find/replace slot. Returns the colour unchanged where the match weight is
// zero, so slots can be chained without a branch per slot.
vec3 applySlot(vec3 c, vec3 find, vec3 rep, float tol, float soft, float hueOnly){
float d;
if (matchSpace <= 0){
d = length(c - find);
} else if (matchSpace <= 1){
d = hueDist(c, find);
} else {
d = abs(lum(c) - lum(find)) * 2.0;
}
float w = 1.0 - smoothstep(tol, tol + max(soft, 0.01), d);
vec3  t = rep;
if (hueOnly > 0.5){
// Keep the source luminance and take only the replacement's hue: recolour
// without flattening the shading underneath.
t = rep * (lum(c) / max(lum(rep), 1e-4));
}
return mix(c, t, w);
}

void main(){
vec2 lp  = acLayerNorm;
vec4 src = fetchL(lp);

float a  = max(src.a, 1e-4);
vec3 sc  = src.rgb / a;

vec3 c = sc;
c = applySlot(c, findCol1.rgb, repCol1.rgb, tol1, soft1, hueOnly1);
c = applySlot(c, findCol2.rgb, repCol2.rgb, tol2, soft2, hueOnly2);
c = applySlot(c, findCol3.rgb, repCol3.rgb, tol3, soft3, hueOnly3);

float l = lum(c);
c = sat3v(mix(vec3(l), c, satBoost));
c = sat3v(mix(sc, c, replaceMix));

vec3  col = mix(sc, c, mixAmt);
float oA  = src.a * opacity;
gl_FragColor = vec4(col * oA, oA);
}
